local function draw_top_sprites()
    pinball.clear_sprites()
    local scx = pinball.get_hram("scx")
    local scy = pinball.get_hram("scy")

    -- Launch Alley #1 at world (168, 152)
    pinball.load_sprite_data("launch_alley_idle", 0, 152 - scy, 168 - scx)

    -- Bumper #1 at world (80, 64)
    pinball.load_sprite_data("bumper_idle", 0, 64 - scy, 80 - scx)

    -- Ball
    local bx = (pinball.get_ball_x() >> 8) - scx
    local by = (pinball.get_ball_y() >> 8) - scy
    pinball.load_sprite_data("ball_spin", pinball.get_ball_spin() >> 5, by, bx)
end

local function draw_bottom_sprites()
    pinball.clear_sprites()
    local scx = pinball.get_hram("scx")
